	if (oldBeforeUnmount) oldBeforeUnmount(vnode);

	const c = vnode._component;
	if (c && c.__hooks) {
		try {
			hookHost.invokeCleanup(c, 0);
		} catch (e) {
			options._catchError(e, hookHost._frame._vnode || c._vnode);
		}
	}
